import Link from "next/link";import {Footer} from "@/components/Footer";import {Header} from "@/components/Header";import {VehicleCard} from "@/components/VehicleCard";import {getDealer,getVehicles} from "@/lib/api";
export default async function Home(){const [dealer,vehicles]=await Promise.all([getDealer(),getVehicles()]);const featured=vehicles.filter(v=>v.is_featured);const lead=featured[0]||vehicles[0];return <><Header dealer={dealer}/><main id="main" style={{"--brand":dealer.primary_color,"--accent":dealer.accent_color} as React.CSSProperties}><section className="hero"><div className="heroCopy"><span className="eyebrow light">Independent motor atelier · Lagos</span><h1>Worth<br/><span className="accentWord">the drive.</span></h1><p>{dealer.tagline}</p><div className="heroActions"><Link className="button light" href="/inventory">View the collection <span>↗</span></Link><a className="quietLink" href="#approach">How we work <span>↓</span></a></div></div>{lead&&<Link href={`/vehicles/${lead.slug}`} className="heroVehicle"><div className="heroImage">{lead.images[0]&&<img src={lead.images[0].url} alt={lead.images[0].alt_text}/>}<div className="heroOverlay"/></div><div className="heroCaption"><span>Featured / {lead.year}</span><strong>{lead.make} {lead.model}</strong><span>View vehicle ↗</span></div></Link>}<div className="heroRail"><span>01</span><span>Curated pre-owned vehicles</span><span>Lagos, NG</span></div></section><section className="collection section"><div className="sectionHead"><div><span className="eyebrow">Selected inventory · 01</span><h2>The current<br/><span className="accentWord">edit.</span></h2></div><p>Distinctive vehicles, selected for condition, character and everyday relevance—not simply a badge.</p></div><div className="editorialGrid">{vehicles.slice(0,3).map((v,i)=><VehicleCard key={v.id} vehicle={v} index={i} editorial/>)}</div><div className="sectionFoot"><span>{vehicles.length} vehicles currently presented</span><Link className="lineLink" href="/inventory">Explore all inventory <b>↗</b></Link></div></section><section className="approach" id="approach"><div className="approachTitle"><span className="eyebrow light">Our approach · 02</span><h2>Less theatre.<br/><span className="accentWord">More clarity.</span></h2></div><div className="approachBody"><p className="approachIntro">{dealer.story}</p><ol><li><span>01</span><div><strong>Useful detail</strong><p>Condition, history and known issues presented in plain language.</p></div></li><li><span>02</span><div><strong>Human guidance</strong><p>A real conversation before any commitment or paperwork.</p></div></li><li><span>03</span><div><strong>Your pace</strong><p>An offer opens a discussion. It never silently completes a sale.</p></div></li></ol></div></section><section className="visitPanel"><div><span className="eyebrow">The showroom · 03</span><h2>See the details<br/>in daylight.</h2></div><div><p>{dealer.address}</p><p>{dealer.opening_hours}</p><Link className="button dark" href="/inventory">Choose a vehicle <span>↗</span></Link></div></section></main><Footer dealer={dealer}/></>}
