import Link from "next/link";import type {Dealer} from "@/lib/types";
export function Header({dealer}:{dealer:Dealer}){const initials=dealer.name.split(" ").map(x=>x[0]).join("").slice(0,2);return <header className="siteHeader"><Link className="brandLockup" href="/" aria-label={`${dealer.name} home`}><span className="brandMark">{initials}</span><span className="wordmark">{dealer.name}<small>Motor atelier · Lagos</small></span></Link><nav aria-label="Main navigation"><Link href="/inventory">Collection</Link><Link href="/#approach">Our approach</Link><Link href="/#contact">Showroom</Link></nav><Link className="headerCta" href="/inventory"><span>Explore stock</span><b aria-hidden="true">↗</b></Link></header>}
